/bin/bash -lc "node --input-type=module <<'NODE'
const base = 'http://localhost:3123'
for (const [path, expectedName, expectedPrice] of [
  ['/products/lamp?currency=EUR', 'Brass lamp', 'EUR 110.40'],
  ['/products/lamp?currency=USD', 'Brass lamp', 'USD 120.00'],
  ['/products/vase?currency=EUR', 'Stone vase', 'EUR 73.60'],
  ['/products/lamp?currency=EUR', 'Brass lamp', 'EUR 110.40'],
]) {
  const start = Date.now()
  const response = await fetch(base + path)
  const reader = response.body.getReader()
  const decoder = new TextDecoder()
  let html = ''
  const seen = new Map()
  for (;;) {
    const { value, done } = await reader.read()
    if (done) break
    html += decoder.decode(value, { stream: true })
    for (const marker of ['Loading product', expectedName, expectedPrice, 'Finding more items', 'Related products']) {
      if ("'!seen.has(marker) && html.includes(marker)) seen.set(marker, Date.now() - start)
    }
  }
  if (response.status !== 200 || !html.includes(expectedName) || !html.includes(expectedPrice)) {
    throw new Error(`${path}: status ${response.status}, missing expected product or price`)
  }
  console.log(path, `status=${response.status}`, `markers=${JSON.stringify(Object.fromEntries(seen))}`)
}
const missing = await fetch(base + '"'/products/missing?currency=EUR')
console.log('/products/missing?currency=EUR', "'`status=${missing.status}`)
if (missing.status !== 404) throw new Error('"'Unknown product did not return 404')
NODE"

